# Source-only fixed-seed training, no target performance or sealed subjects.
import os,sys,json,base64,zlib,subprocess,hashlib,requests
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir(exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code)
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
raw=Path('/kaggle/working/raw_source');raw.mkdir(exist_ok=True)
revision='381ac26'
(out/'runner_provenance.json').write_text(json.dumps(dict(seed=20261013,git_commit=revision,runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='source subjects1-18 official train only; no target performance'),indent=2))
tests=sorted(str(p) for p in (code/'tests').glob('test_*.py'))
result=subprocess.run([sys.executable,'-m','pytest','-q',*tests],cwd=code,text=True,capture_output=True)
(out/'pytest.txt').write_text(result.stdout+result.stderr);print(result.stdout,flush=True)
if result.returncode:raise RuntimeError('source portable policy/integration tests failed')
import torch
if not torch.cuda.is_available():raise RuntimeError('GPU required for source training job')
base='https://s3.ap-northeast-1.wasabisys.com/gigadb-datasets/live/pub/10.5524/100001_101000/100542/'
files=[]
def download(url,path):
 digest=hashlib.sha256()
 with requests.get(url,stream=True,timeout=(30,300)) as response:
  response.raise_for_status()
  with path.open('wb') as target:
   for chunk in response.iter_content(1024*1024):target.write(chunk);digest.update(chunk)
 return dict(url=url,file=path.name,sha256=digest.hexdigest(),bytes=path.stat().st_size)
for subject in range(1,19):
 name=f'sess01_subj{subject:02d}_EEG_ERP.mat';print('source download',subject,flush=True)
 files.append(download(base+f'session1/s{subject}/'+name,raw/name))
 (out/'source_download_manifest.json').write_text(json.dumps(files,indent=2))
schedule=raw/'schedule.mat'
meta=download('https://raw.githubusercontent.com/PatternRecognition/OpenBMI/master/GigaScience/function_ERP/random_cell_order.mat',schedule)
(out/'schedule_download.json').write_text(json.dumps(meta,indent=2))
for seed in (20261013,20261014,20261015):
 subprocess.run([sys.executable,str(code/'scripts/train_openbmi_source.py'),'--config',str(code/'configs/openbmi_reliability_stage_a.json'),'--raw-dir',str(raw),'--schedule',str(schedule),'--out-dir',str(out),'--seed',str(seed),'--git-commit',revision],check=True)
(out/'completion.json').write_text(json.dumps(dict(status='three source checkpoints complete, no independent evaluation',seeds=[20261013,20261014,20261015],git_commit=revision),indent=2))
